using namespace transmission;
bool isTransmissionMate(const std::string& kind){return kind=="gear"||kind=="chain"||kind=="belt"||kind=="shaft";}
bool transmissionMotionField(const std::string& type,const std::string& key){
    if(!isTransmissionMate(type))return false;
    if(key=="efficiency"||key=="service_factor")return true;
    if(type=="shaft")return key=="diameter_mm"||key=="inner_diameter_mm"||key=="length_mm"||key=="shear_modulus_GPa"||key=="allowable_shear_MPa"||key=="stress_concentration"||key=="max_twist_deg";
    if(key=="teeth_a"||key=="teeth_b"||key=="phase_deg"||key=="face_width_mm"||key=="center_distance_mm"||key=="enforce_center_distance"||key=="center_tolerance_mm"||key=="length_tolerance_mm"||key=="axial_tolerance_mm"||key=="allowable_tangential_force_N")return true;
    if(type=="gear")return key=="pitch_diameter_a_mm"||key=="pitch_diameter_b_mm"||key=="module_mm"||key=="pressure_angle_deg"||key=="helix_angle_deg"||key=="helix_b_deg"||key=="internal"||key=="double_helical"||key=="center_gap_mm"||key=="left_load_fraction"||key=="lewis_factor_a"||key=="lewis_factor_b"||key=="allowable_bending_MPa";
    if(type=="chain")return key=="pitch_mm"||key=="links"||key=="allowable_chain_pull_N";
    return key=="pitch_mm"||key=="pitch_diameter_a_mm"||key=="pitch_diameter_b_mm"||key=="synchronous"||key=="crossed"||key=="pretension_N"||key=="friction_coefficient"||key=="allowable_belt_tension_N"||key=="belt_teeth";
}
bool extendedTransmissionDocument(const Document& d){for(const auto& m:d.mates){if(m.type=="belt")return true;if(isTransmissionMate(m.type))for(const auto& field:m.motion)if(field.first!="teeth_a"&&field.first!="teeth_b"&&field.first!="phase_deg")return true;}return false;}
