V evaluateTransmissionMate(const AssemblyMate& m,const ExprEnv& env,double center,double offset){V p=V::makeObj();for(const auto& [key,expression]:m.motion){bool ok=false;double value=evalExpr(expression,env,&ok);if(!ok||!std::isfinite(value)||std::abs(value)>1e6)throw std::runtime_error("MECHANICAL_INVALID_EXPRESSION: "+key);add(p,key.c_str(),value);}return evaluateTransmissionPair(m.type,p,center,offset);}
