        const double d=number(p,"diameter_mm"),j=get(pair,"polar_moment_mm4").num;require(j>0,"invalid shaft polar moment");double stress=torque*1000*(d/2)/j*number(p,"stress_concentration",1)*service;add(r,"shaft_shear_MPa",stress);
        if(p.find("allowable_shear_MPa")){if(stress>0)add(r,"shaft_shear_safety_factor",number(p,"allowable_shear_MPa")/stress);else r.set("shaft_shear_status",V::makeStr("unloaded"));r.set("shaft_shear_pass",V::makeBool(stress<=number(p,"allowable_shear_MPa")));}
