        if(kind=="gear"){double beta=deg2rad(number(p,"helix_angle_deg")),at=deg2rad(number(pair,"transverse_pressure_angle_deg",20));add(r,"radial_force_N",ft*std::tan(at));double axial=ft*std::tan(std::abs(beta));if(number(p,"double_helical")==1){add(r,"ideal_balanced_net_axial_force_N",0);add(r,"ideal_axial_force_per_half_N",axial/2);if(p.find("left_load_fraction")){double fraction=number(p,"left_load_fraction");add(r,"net_axial_force_magnitude_N",axial*std::abs(2*fraction-1));add(r,"left_half_axial_force_N",axial*fraction);add(r,"right_half_axial_force_N",axial*(1-fraction));}r.set("axial_balance_verified",V::makeBool(false));}else add(r,"axial_force_magnitude_N",axial);
            if(p.find("face_width_mm")&&p.find("lewis_factor_a")&&p.find("lewis_factor_b")){double width=number(p,"face_width_mm")-number(p,"center_gap_mm"),module=number(pair,"normal_module_mm");require(width>0,"active face width must be positive");const double share=number(p,"double_helical")==1&&p.find("left_load_fraction")?2*std::max(number(p,"left_load_fraction"),1-number(p,"left_load_fraction")):1;double stressA=ft*share/(width*module*number(p,"lewis_factor_a")),stressB=ft*share/(width*module*number(p,"lewis_factor_b"));add(r,"lewis_bending_a_MPa",stressA);add(r,"lewis_bending_b_MPa",stressB);r.set("lewis_scope",V::makeStr("screening with caller Y defined by Ft=sigma*width*normal_module*Y; active face width; not ISO/AGMA fatigue/contact rating"));if(p.find("allowable_bending_MPa"))r.set("lewis_bending_pass",V::makeBool(std::max(stressA,stressB)<=number(p,"allowable_bending_MPa")));}
        }else if(kind=="chain"){double pitch=number(p,"pitch_mm"),z=number(pair,"teeth_a"),pull=2*K_PI*torque*1000/(pitch*z)*service;add(r,"mean_chain_speed_m_s",pitch*z*std::abs(rpm)/60000);add(r,"mean_chain_pull_N",pull);if(p.find("allowable_chain_pull_N"))r.set("chain_pull_pass",V::makeBool(pull<=number(p,"allowable_chain_pull_N")));}
